-- SET STATISTICS takes a signed integer, or DEFAULT since Postgres 17.
-- gram.y uses the same set_statistics_value rule for every statement below.
-- https://www.postgresql.org/docs/17/sql-altertable.html
ALTER TABLE t ALTER COLUMN c SET STATISTICS 100;
ALTER TABLE t ALTER COLUMN c SET STATISTICS -1;
ALTER TABLE t ALTER COLUMN c SET STATISTICS DEFAULT;
ALTER TABLE t ALTER c SET STATISTICS DEFAULT;
ALTER TABLE IF EXISTS t
    ALTER COLUMN a SET STATISTICS DEFAULT,
    ALTER COLUMN b SET STATISTICS 500;

ALTER FOREIGN TABLE ft ALTER COLUMN c SET STATISTICS DEFAULT;

ALTER INDEX i ALTER COLUMN 1 SET STATISTICS DEFAULT;
ALTER INDEX i ALTER 2 SET STATISTICS -1;

ALTER MATERIALIZED VIEW mv ALTER COLUMN c SET STATISTICS DEFAULT;
ALTER MATERIALIZED VIEW mv ALTER c SET STATISTICS -1;

ALTER STATISTICS s1 SET STATISTICS DEFAULT;
ALTER STATISTICS IF EXISTS s1 SET STATISTICS -1;
